avail = {"mem": 16, "cores": 16}
need = {"mem": 2, "cores": 1, "count": 5}
launched = 0
rounds = 0
while launched < need["count"] and rounds < 10:
    rounds += 1
    remaining = need["count"] - launched
    grant = 0
    for _ in range(remaining):
        if avail["mem"] >= need["mem"] and avail["cores"] >= need["cores"]:
            avail["mem"] -= need["mem"]
            avail["cores"] -= need["cores"]
            grant += 1
    if grant == 0:
        print(f"round {rounds}: no resources, AM waits")
        break
    launched += grant
    print(f"round {rounds}: RM granted {grant} containers, total launched={launched}, avail mem={avail['mem']} cores={avail['cores']}")
print(f"all {need['count']} tasks launched in {rounds} heartbeat rounds")
